import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int md = sc.nextInt();

        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];

        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % md;
        }

        // Modular exponentiation
        long modPow(long base, int exp) {
            long res = 1;
            while (exp > 0) {
                if ((exp & 1) == 1) res = res * base % md;
                base = base * base % md;
                exp >>= 1;
            }
            return res;
        }

        invFact[n] = modPow(fact[n], md - 2);
        for (int i = n; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % md;
        }

        // nCr function
        long nCr(int a, int b) {
            if (b < 0 || b > a) return 0;
            return fact[a] * invFact[b] % md * invFact[a - b] % md;
        }

        long[] g = new long[n + 1];
        long[] f = new long[n + 1];

        g[0] = 1;
        f[0] = 0;

        for (int i = 1; i <= n; i++) {
            g[i] = 1;
            f[i] = 0;
            for (int j = 1; j <= i; j++) {
                long now = nCr(i - 1, j - 1) * (i + 1) % md;
                g[i] = (g[i] + g[j - 1] * g[i - j] % md * now) % md;
                f[i] = (f[i] + f[j - 1] * g[i - j] % md * now) % md;
                f[i] = (f[i] + g[j - 1] * f[i - j] % md * now) % md;
                long add_value = ((long)(j - 1) * j / 2 + (long)(i - j) * (i - j + 1) / 2);
                f[i] = (f[i] + nCr(i - 1, j - 1) * g[j - 1] % md * g[i - j] % md * add_value) % md;
            }
        }

        long[][][] dp = new long[n + 1][m + 1][2];
        long[][][] dp2 = new long[n + 1][m + 1][2];

        dp[0][0][1] = 0;
        dp2[0][0][1] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                dp[i][j][1] = (dp[i - 1][j][0] + dp[i - 1][j][1]) % md;
                dp2[i][j][1] = (dp2[i - 1][j][0] + dp2[i - 1][j][1]) % md;
                for (int k = 1; k <= j; k++) {
                    long c = nCr(j, k);
                    long val1 = (dp2[i - k][j - k][1] * f[k]) % md;
                    long val2 = (dp[i - k][j - k][1] * g[k]) % md;
                    dp[i][j][0] = (dp[i][j][0] + c * val1) % md;
                    dp[i][j][0] = (dp[i][j][0] + c * val2) % md;
                    dp2[i][j][0] = (dp2[i][j][0] + c * val2) % md;
                }
            }
        }

        System.out.println((int)((dp[n][m][0] + dp[n][m][1]) % md));
    }
}

